def _fail(message):
    print(f"presets: {message}", file=sys.stderr)
    raise SystemExit(2)


def _default_out(mode, smoke):
    if smoke:
        return f"{SMOKE_PREFIX}opencode/flower-smoke/{mode}"
    return f"runs/{mode}"


def resolve(mode, out=None, weights=None, tag=None, smoke=False):
    """把 (mode, CLI 覆盖项) 解析为全部生效配置。

    返回字典恰含 D1 规定的 22 个键。强制规则不合一律 SystemExit(2)。
    """
    if mode == "all":
        _fail("resolve() 不接受 mode='all'，请由 main() 循环四个 canonical mode")
    if mode not in CANONICAL_MODES:
        _fail(f"未知 mode: {mode!r}（canonical: {', '.join(CANONICAL_MODES)}）")

    preset = PRESETS[mode]
    if out is None:
        out = _default_out(mode, smoke)
    out_str = str(out)
    if not out_str:
        _fail("out 不能为空")

    weights_init = preset["weights"] if weights is None else weights
    if weights_init not in ("imagenet1k_v1", "none"):
        _fail(f"weights 必须为 imagenet1k_v1 或 none，收到 {weights_init!r}")
    weights_overridden = weights is not None and weights != preset["weights"]

    if smoke:
        resolved = Path(out_str).resolve()
        if resolved == Path("/tmp") or not resolved.is_relative_to(Path("/tmp")):
            _fail(f"smoke run 的 --out 必须是 /tmp 下的子目录（不能恰为 /tmp）: {out_str}")
        if not tag:
            tag = "smoke"
        if out_str.startswith("runs/"):
            _fail(f"smoke run 不得写入 runs/: {out_str}")
    else:
        if weights_overridden:
            if not out_str.startswith(DIAG_PREFIX):
                _fail(
                    "覆盖 --weights 且与预设不同时，--out 必须以 "
                    f"{DIAG_PREFIX} 开头: {out_str}"
                )
            if tag is None:
                tag = Path(out_str).name
            if not tag or tag == mode:
                _fail(f"诊断 run 的 --tag 必须非空且不等于 mode: {tag!r}")
        else:
            if out_str != f"runs/{mode}":
                _fail(f"预设 run 的 --out 必须恰为 runs/{mode}: {out_str}")
            if tag is None:
                tag = mode
            if tag != mode:
                _fail(f"预设 run 的 --tag 必须等于 mode: {tag!r}")

    stage1 = int(preset["stage1_epochs"])
    stage2 = int(preset["stage2_epochs"])
    epochs_planned = stage1 + stage2
    unfreeze_epoch = stage1 + 1 if stage1 > 0 else None
    if preset["bn_stage2"] is not None:
        bn_mode = "frozen_to_train"
    else:
        bn_mode = preset["bn_stage1"]
    if stage1 == 0 and preset["lr_backbone"] > 0:
        params_rule = "all"
    else:
        params_rule = "fc_only"

    return {
        "mode": mode,
        "tag": str(tag),
        "is_diag": (not smoke) and out_str.startswith(DIAG_PREFIX),
        "smoke": bool(smoke),
        "base": preset["base"],
        "weights_init": weights_init,
        "epochs_planned": epochs_planned,
        "stage1_epochs": stage1,
        "stage2_epochs": stage2,
        "unfreeze_epoch": unfreeze_epoch,
        "bn_stage1": preset["bn_stage1"],
        "bn_stage2": preset["bn_stage2"],
        "bn_mode": bn_mode,
        "params_trainable_stage1_rule": params_rule,
        "lr_head": preset["lr_head"],
        "lr_backbone": preset["lr_backbone"],
        "weight_decay": preset["weight_decay"],
        "batch": preset["batch"],
        "aug": preset["aug"],
        "aug_ops": list(AUG_OPS[preset["aug"]]),
        "label_smoothing": preset["label_smoothing"],
        "out": out_str,
    }


def _check():
    problems = []
    if set(_EXPECTED) != set(PRESETS):
        problems.append(f"mode 集合不一致: {sorted(_EXPECTED)} vs {sorted(PRESETS)}")
    for mode in CANONICAL_MODES:
        if mode not in PRESETS or mode not in _EXPECTED:
            continue
        actual = PRESETS[mode]
        expected = _EXPECTED[mode]
        if set(actual) != set(expected):
            problems.append(
                f"{mode}: 键集合不一致 {sorted(actual)} vs {sorted(expected)}"
            )
            continue
        for key in _EXPECTED_KEYS:
            got, want = actual[key], expected[key]
            if isinstance(want, float) or isinstance(got, float):
                if not isinstance(got, (int, float)) or isinstance(got, bool):
                    problems.append(f"{mode}.{key}: 非数值 {got!r}")
                elif abs(float(got) - float(want)) > 1e-12:
                    problems.append(f"{mode}.{key}: {got!r} != {want!r}")
            elif got != want:
                problems.append(f"{mode}.{key}: {got!r} != {want!r}")
    if problems:
        for item in problems:
            print(f"presets check FAIL: {item}", file=sys.stderr)
        return 1
    print("presets check ok")
    return 0


_RESOLVE_FROM_MODE = object()


def _main(argv=None):
    parser = argparse.ArgumentParser(description="四组预设与 resolve()")
    action = parser.add_mutually_exclusive_group()
    action.add_argument("--json", action="store_true", help="输出四组 resolve 结果")
    action.add_argument("--check", action="store_true", help="与冻结期望表逐字段比对")
    action.add_argument(
        "--resolve",
        nargs="?",
        const=_RESOLVE_FROM_MODE,
        metavar="MODE",
        help="解析单个 mode（可写 --resolve MODE 或 --resolve --mode MODE）",
    )
    parser.add_argument("--mode", help="与 --resolve 搭配使用的 canonical mode")
    parser.add_argument("--out")
    parser.add_argument("--weights")
    parser.add_argument("--tag")
    parser.add_argument("--smoke", action="store_true")
    args = parser.parse_args(argv)

    if args.check:
        return _check()
    if args.json:
        result = {
            mode: resolve(mode, out=args.out, weights=args.weights, tag=args.tag)
            for mode in CANONICAL_MODES
        }
        print(json.dumps(result, indent=2, sort_keys=True))
        return 0
    if args.resolve is not None:
        if args.resolve is _RESOLVE_FROM_MODE:
            mode = args.mode
        else:
            mode = args.resolve
            if args.mode is not None and args.mode != mode:
                print(
                    f"presets: --resolve {mode} 与 --mode {args.mode} 冲突",
                    file=sys.stderr,
                )
                return 2
        if not mode:
            print(
                "presets: --resolve 需要 mode，请用 --resolve --mode <mode> 或 --resolve <mode>",
                file=sys.stderr,
            )
            return 2
        result = resolve(
            mode,
            out=args.out,
            weights=args.weights,
            tag=args.tag,
            smoke=args.smoke,
        )
        print(json.dumps(result, indent=2, sort_keys=True))
        return 0
    parser.print_help()
    return 0
# ==== from scripts/data_split.py ====
"""确定性 train/val/test 划分与指纹（阶段 A）。

划分算法不得使用 random / numpy 随机：
  1. 对类 L（1..102 升序），取 meta.csv 中 split ∈ {train,val} 且 label==L 的 image_id；
  2. 每个 image_id 计算 k = sha256(f"{split_seed}:{image_id}").hexdigest()；
  3. 按 (k, image_id) 升序排序；
  4. 前 val_per_class 个 → val，其余 → train，均保持该排序；
  5. 类号升序展平 train/val；test 按 meta.csv 行序。

理由：random.shuffle 不在跨解释器版本稳定契约内；hash 排序给契约保证。
"""

import argparse
import csv
import hashlib
import sys
from pathlib import Path



def _read_meta(meta_csv):
    """返回 (train_val_by_class, test_rows)。test_rows 保持 meta.csv 行序。"""
    by_class = {label: [] for label in range(1, NUM_CLASSES + 1)}
    test_rows = []
    with Path(meta_csv).open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        for row in reader:
            image_id = row["image_id"]
            label = int(row["label"])
            split = row["split"]
            if split == "test":
                test_rows.append((image_id, label))
            elif split in ("train", "val"):
                by_class.setdefault(label, []).append(image_id)
    return by_class, test_rows


def _hash_key(split_seed, image_id):
    return hashlib.sha256(f"{split_seed}:{image_id}".encode("ascii")).hexdigest()


def build_split(meta_csv, split_seed=SPLIT_SEED, val_per_class=VAL_PER_CLASS):
    """纯函数：按 hash 分桶生成 {'train': [...], 'val': [...], 'test': [...]}。"""
    by_class, test_rows = _read_meta(meta_csv)
    train_rows = []
    val_rows = []
    for label in range(1, NUM_CLASSES + 1):
        names = by_class.get(label, [])
        ordered = sorted(names, key=lambda image_id: (_hash_key(split_seed, image_id), image_id))
        val_rows.extend((image_id, label) for image_id in ordered[:val_per_class])
        train_rows.extend((image_id, label) for image_id in ordered[val_per_class:])
    return {"train": train_rows, "val": val_rows, "test": test_rows}


def split_fingerprint(split):
    """train/val/test 依次拼接 "{split}:{image_id},{label}\\n" 的 SHA-256。"""
    digest = hashlib.sha256()
    for part in ("train", "val", "test"):
        for image_id, label in split[part]:
            digest.update(f"{part}:{image_id},{label}\n".encode("utf-8"))
    return digest.hexdigest()


def _meta_sha256(meta_csv):
    return hashlib.sha256(Path(meta_csv).read_bytes()).hexdigest()


def _report(meta_csv, split_seed, val_per_class):
    split = build_split(meta_csv, split_seed=split_seed, val_per_class=val_per_class)
    fingerprint = split_fingerprint(split)
    print(f"meta_sha256 {_meta_sha256(meta_csv)}")
    print(
        "counts "
        f"train={len(split['train'])} val={len(split['val'])} test={len(split['test'])}"
    )
    print(f"split_fingerprint {fingerprint}")
    return split, fingerprint


def _verify(meta_csv, split_seed, val_per_class):
    problems = []
    meta_digest = _meta_sha256(meta_csv)
    if meta_digest != META_SHA256:
        problems.append(f"meta.csv sha256 不匹配: {meta_digest} != {META_SHA256}")

    split = build_split(meta_csv, split_seed=split_seed, val_per_class=val_per_class)
    fingerprint = split_fingerprint(split)
    expected = {
        "train": TRAIN_N,
        "val": VAL_N,
        "test": TEST_N,
    }
    for part, want in expected.items():
        got = len(split[part])
        if got != want:
            problems.append(f"{part} 数量不匹配: {got} != {want}")
    if fingerprint != SPLIT_FINGERPRINT:
        problems.append(f"划分指纹不匹配: {fingerprint} != {SPLIT_FINGERPRINT}")

    # 自检：seed 0 与 seed 1 必须给出不同划分（防止 hash 键退化为常量）。
    if split_seed == SPLIT_SEED and val_per_class == VAL_PER_CLASS:
        alt = split_fingerprint(
            build_split(meta_csv, split_seed=SPLIT_SEED + 1, val_per_class=val_per_class)
        )
        if alt == fingerprint:
            problems.append("split_seed=0 与 split_seed=1 的划分指纹相同，hash 分桶失效")

    print(f"meta_sha256 {meta_digest}")
    print(
        "counts "
        f"train={len(split['train'])} val={len(split['val'])} test={len(split['test'])}"
    )
    print(f"split_fingerprint {fingerprint}")
    if problems:
        for item in problems:
            print(f"data_split FAIL: {item}", file=sys.stderr)
        return 3
    print("OK")
    return 0


def main(argv=None):
    parser = argparse.ArgumentParser(description="确定性划分与指纹校验")
    parser.add_argument("--verify", action="store_true", help="按契约常量校验并退出 0/3")
    parser.add_argument("--split-seed", type=int, default=SPLIT_SEED)
    parser.add_argument("--val-per-class", type=int, default=VAL_PER_CLASS)
    parser.add_argument(
        "--meta",
        default=str(Path(__file__).resolve().parents[1] / "data" / "meta.csv"),
    )
    args = parser.parse_args(argv)

    if args.verify:
        return _verify(Path(args.meta), args.split_seed, args.val_per_class)
    _report(Path(args.meta), args.split_seed, args.val_per_class)
    return 0
